use std::collections::HashMap;

fn main() {
    // into a Vec
    let squares: Vec<i32> = (1..=4).map(|n| n * n).collect();
    println!("{:?}", squares);

    // _ lets Rust fill in the item type itself (i32 here)
    let cubes: Vec<_> = (1..4).map(|n| n * n * n).collect();
    println!("{:?}", cubes);

    // into a String: chars() is an iterator over the characters of a &str
    let shout: String = "hello".chars().map(|c| c.to_ascii_uppercase()).collect();
    let reversed = "hello".chars().rev().collect::<String>();
    println!("{shout} {reversed}");

    // into a HashMap: the items must be (key, value) tuples
    // iter() gives &&str items; *w turns each one into the &str used as the key
    let words = ["fig", "pear", "banana"];
    let lengths: HashMap<&str, usize> = words.iter().map(|w| (*w, w.len())).collect();
    println!("pear has {} letters", lengths["pear"]);
    println!("{} entries", lengths.len());
}

fn main() {
    let nums = vec![4, 8, 15, 16, 23, 42];

    let total: i32 = nums.iter().sum();
    let how_many = nums.iter().count();
    let squares_sum = nums.iter().fold(0, |acc, n| acc + n * n);
    println!("sum {total}, count {how_many}, sum of squares {squares_sum}");

    println!("max {:?}, min {:?}", nums.iter().max(), nums.iter().min());

    let first_big = nums.iter().find(|n| **n > 10);
    println!("first over 10: {:?}", first_big);

    let any_odd = nums.iter().any(|n| n % 2 == 1);
    let all_positive = nums.iter().all(|n| *n > 0);
    println!("any odd: {any_odd}, all positive: {all_positive}");
}

// Output:
// sum 108, count 6, sum of squares 2854
// max Some(42), min Some(4)
// first over 10: Some(15)
// any odd: true, all positive: true

fn main() {
    let text = "the quick brown fox jumps over the lazy dog";
    let long_words = text.split_whitespace().filter(|w| w.len() > 3).count();
    println!("{long_words} long words");

    let longest = text.split_whitespace().max_by_key(|w| w.len());
    println!("longest: {:?}", longest);
}

