exercise.solution:
fn total_length(words: &[&str]) -> usize {
    words.iter().map(|w| w.len()).sum()
}

fn count_long(words: &[&str]) -> usize {
    words.iter().filter(|w| w.len() > 2).count()
}

fn main() {
    let words = ["rust", "is", "fun"];
    println!("{}", total_length(&words));
    println!("{}", count_long(&words));
}
